@Test
public void testRun() throws Exception {
    // Setup config and mocks
    final long durationToRetain = TimeUnit.HOURS.toMillis(2);
    TaskLogAutoCleanerConfig cleanerConfig = new TaskLogAutoCleanerConfig(true, 2000L, 1000L, durationToRetain);
    TaskStorage taskStorage = Mockito.mock(TaskStorage.class);
    TaskLogKiller taskLogKiller = Mockito.mock(TaskLogKiller.class);
    TaskLogAutoCleaner taskLogAutoCleaner = new TaskLogAutoCleaner(taskLogKiller, cleanerConfig, taskStorage);
    long expectedExpiryTime = System.currentTimeMillis() - durationToRetain;
    taskLogAutoCleaner.run();
    // Verify that kill on TaskStorage and TaskLogKiller is invoked with the correct timestamp
    Mockito.verify(taskStorage).removeTasksOlderThan(ArgumentMatchers.longThat(observedExpiryTime -> observedExpiryTime >= expectedExpiryTime));
    Mockito.verify(taskLogKiller).killOlderThan(ArgumentMatchers.longThat(observedExpiryTime -> observedExpiryTime >= expectedExpiryTime));
}

